import React, { useState, useEffect, useRef, useCallback, memo } from 'react';
import { useGesture } from '@use-gesture/react';

// ── Custom hook for keyboard shortcuts ──
const useKeyboardShortcuts = (handlers, deps = []) => {
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (handlers[e.key.toLowerCase()]) {
        handlers[e.key.toLowerCase()](e);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handlers, ...deps]);
};

// ── Optimized Hotspot ──
const Hotspot = memo(({ hotspot, onClick, zoomLevel }) => (
  <button
    className="absolute flex items-center justify-center w-10 h-10 text-2xl transition-all duration-200 border-2 border-blue-500 rounded-full shadow-lg bg-white/80 hover:bg-white hover:scale-110"
    style={{
      left: `${hotspot.x}%`,
      top: `${hotspot.y}%`,
      transform: `translate(-50%, -50%) scale(${Math.max(0.7, 1 / zoomLevel)})`,
    }}
    onClick={(e) => onClick(hotspot, e)}
    title={hotspot.title}
    aria-label={`Hotspot: ${hotspot.title}`}
  >
    •
  </button>
));
Hotspot.displayName = 'Hotspot';

// ── Control Button ──
const ControlButton = memo(({ icon, onClick, title, className = '' }) => (
  <button
    onClick={onClick}
    className={`p-3 bg-black/60 backdrop-blur-md text-white rounded-full hover:bg-black/80 transition-all shadow-lg ${className}`}
    title={title}
    aria-label={title}
  >
    {icon}
  </button>
));
ControlButton.displayName = 'ControlButton';

// ── Main Viewer ──
const InteractiveViewer = memo(({
  selectedLocation,
  locationMap,
  isFullscreen,
  setIsFullscreen,
  zoomLevel,
  setZoomLevel,
  showHotspots,
  setShowHotspots,
  showInfo,
  toggleInfo,
  audioEnabled,
  toggleAudio,
  viewMode,
  changeViewMode,
  chatOpen,
  setChatOpen,
  chatMessages,
  chatInput,
  setChatInput,
  handleChatSend,
}) => {
  const [rotation, setRotation] = useState({ yaw: 0, pitch: 0 }); // yaw = horizontal, pitch = vertical
  const viewerRef = useRef(null);
  const [currentHotspot, setCurrentHotspot] = useState(null);
  const [showCopiedToast, setShowCopiedToast] = useState(false);

  const loc = locationMap[selectedLocation];

  // ── Gesture handling with use-gesture ──
  const bind = useGesture(
    {
      onDrag: ({ down, movement: [mx, my], pinching, cancel }) => {
        if (pinching) {
          cancel?.();
          return;
        }
        setRotation((prev) => ({
          yaw: (prev.yaw + mx * 0.25) % 360,
          pitch: Math.max(-90, Math.min(90, prev.pitch - my * 0.25)),
        }));
      },

      onPinch: ({ offset: [d], origin: [ox, oy], last, pinching }) => {
        if (last) return;
        const rect = viewerRef.current?.getBoundingClientRect();
        if (!rect) return;

        // Zoom toward pinch center
        const px = (ox - rect.left) / rect.width;
        const py = (oy - rect.top) / rect.height;

        setZoomLevel((prev) => {
          const target = Math.max(0.6, Math.min(3.5, prev * (1 + d * 0.005)));
          // Here you could add offset adjustment for zoom-to-point, but keeping simple for now
          return target;
        });
      },

      onWheel: ({ event, pinching, delta: [, dy] }) => {
        if (pinching) return;
        event.preventDefault();
        setZoomLevel((p) => Math.max(0.6, Math.min(3.5, p - dy * 0.0015)));
      },
    },
    {
      drag: { filterTaps: true, preventDefault: true },
      pinch: { scaleBounds: { min: 0.6, max: 3.5 } },
      wheel: { preventDefault: true },
      target: viewerRef,
      enabled: true,
    }
  );

  // ── Hotspot click ──
  const handleHotspotClick = useCallback((hotspot, e) => {
    e.stopPropagation();
    setCurrentHotspot(hotspot);
    const timer = setTimeout(() => setCurrentHotspot(null), 6000);
    return () => clearTimeout(timer);
  }, []);

  // ── Share ──
  const handleShare = useCallback(async () => {
    const url = loc?.url || window.location.href;
    if (navigator.share) {
      try {
        await navigator.share({
          title: `${selectedLocation} - Jharkhand Virtual Tour`,
          text: loc?.description,
          url,
        });
        return;
      } catch (err) {
        if (err.name !== 'AbortError') console.warn(err);
      }
    }
    // Fallback copy
    try {
      await navigator.clipboard.writeText(url);
      setShowCopiedToast(true);
      setTimeout(() => setShowCopiedToast(false), 2200);
    } catch {}
  }, [selectedLocation, loc]);

  // ── Keyboard controls ──
  useKeyboardShortcuts(
    {
      arrowup: () => setRotation(p => ({ ...p, pitch: Math.max(-90, p.pitch - 6) })),
      arrowdown: () => setRotation(p => ({ ...p, pitch: Math.min(90, p.pitch + 6) })),
      arrowleft: () => setRotation(p => ({ ...p, yaw: p.yaw - 6 })),
      arrowright: () => setRotation(p => ({ ...p, yaw: p.yaw + 6 })),
      '+': () => setZoomLevel(p => Math.min(3.5, p + 0.2)),
      '-': () => setZoomLevel(p => Math.max(0.6, p - 0.2)),
      '0': () => { setZoomLevel(1); setRotation({ yaw: 0, pitch: 0 }); },
      escape: () => {
        if (isFullscreen) setIsFullscreen(false);
        if (currentHotspot) setCurrentHotspot(null);
        if (chatOpen) setChatOpen(false);
      },
      h: () => setShowHotspots(p => !p),
      i: toggleInfo,
      m: toggleAudio,
      f: () => setIsFullscreen(p => !p),
    },
    [isFullscreen, currentHotspot, chatOpen, toggleInfo, toggleAudio, setIsFullscreen, setShowHotspots]
  );

  return (
    <div className="relative w-full h-full overflow-hidden bg-black select-none touch-none" ref={viewerRef} {...bind()}>
      {/* Main 360 background with GPU acceleration */}
      <div
        className="absolute inset-0 origin-center will-change-transform"
        style={{
          transform: `perspective(1500px) rotateX(${rotation.pitch}deg) rotateY(${rotation.yaw}deg) scale(${zoomLevel})`,
          backgroundImage: `url(${loc.image})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          imageRendering: zoomLevel > 1.5 ? 'crisp-edges' : 'auto',
        }}
      />

      {/* Hotspots */}
      {showHotspots &&
        loc.hotspots.map((hotspot) => (
          <Hotspot
            key={hotspot.id}
            hotspot={hotspot}
            onClick={handleHotspotClick}
            zoomLevel={zoomLevel}
          />
        ))}

      {/* Hotspot popup */}
      {currentHotspot && (
        <div
          className="absolute max-w-md p-6 text-white -translate-x-1/2 -translate-y-1/2 border shadow-2xl top-1/2 left-1/2 bg-black/80 backdrop-blur-lg rounded-2xl border-white/20 animate-fadeIn"
          onClick={() => setCurrentHotspot(null)}
        >
          <button className="absolute text-xl top-3 right-4" aria-label="Close">✕</button>
          <h3 className="mb-2 text-xl font-bold">{currentHotspot.title}</h3>
          <p className="text-gray-300">{currentHotspot.description}</p>
          <p className="mt-4 text-xs text-gray-500">Click anywhere to close • Auto-closes in 6s</p>
        </div>
      )}

      {/* Top-right controls – minimal in fullscreen */}
      <div className={`absolute top-4 right-4 flex flex-col gap-3 z-20 ${isFullscreen ? 'scale-90' : ''}`}>
        <ControlButton icon="📍" onClick={() => setShowHotspots(p => !p)} title="Toggle Hotspots (H)" />
        <ControlButton icon={isFullscreen ? "⤢" : "⛶"} onClick={() => setIsFullscreen(p => !p)} title={isFullscreen ? "Exit Fullscreen (F)" : "Fullscreen (F)"} />
        <ControlButton icon="🔗" onClick={handleShare} title="Share" />
      </div>

      {/* Zoom level indicator */}
      <div className="absolute z-20 px-4 py-2 text-sm font-medium text-white rounded-full bottom-20 right-6 bg-black/60 backdrop-blur-md">
        {Math.round(zoomLevel * 100)}%
      </div>

      {/* Bottom hint – hide in fullscreen */}
      {!isFullscreen && (
        <div className="absolute flex items-center gap-4 px-6 py-3 text-sm text-white -translate-x-1/2 rounded-full shadow-xl bottom-4 left-1/2 bg-black/70 backdrop-blur-lg">
          <span>🖱️ Drag / 📱 Pinch to explore</span>
          <span>•</span>
          <span>🔍 Scroll / Pinch to zoom</span>
        </div>
      )}

      {/* Copied toast */}
      {showCopiedToast && (
        <div className="fixed z-50 px-6 py-3 text-white -translate-x-1/2 rounded-full shadow-xl bottom-8 left-1/2 bg-green-600/90 animate-fadeInOut">
          Link copied to clipboard!
        </div>
      )}

      {/* ── Chat toggle button ── */}
      <div className="absolute z-20 bottom-28 left-6">
        {chatOpen ? (
          <div className="overflow-hidden border shadow-2xl bg-gradient-to-br from-blue-900/90 to-indigo-900/90 backdrop-blur-xl rounded-2xl w-80 sm:w-96 border-blue-400/30">
            <div className="flex items-center justify-between p-4 border-b border-blue-400/20">
              <h3 className="font-semibold">Tour Guide AI</h3>
              <button onClick={() => setChatOpen(false)} className="text-xl">✕</button>
            </div>
            <div className="h-64 p-4 space-y-3 overflow-y-auto">
              {chatMessages.map((m, i) => (
                <div key={i} className={`flex ${m.isBot ? 'justify-start' : 'justify-end'}`}>
                  <div className={`max-w-[80%] px-4 py-2 rounded-2xl ${m.isBot ? 'bg-blue-600/30' : 'bg-indigo-500/40'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
            </div>
            <form onSubmit={handleChatSend} className="flex gap-2 p-3 border-t border-blue-400/20">
              <input
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                placeholder="Ask about this place..."
                className="flex-1 px-4 py-2 text-white border rounded-full bg-black/40 border-blue-400/30 focus:outline-none focus:border-blue-400"
              />
              <button type="submit" className="px-5 font-medium bg-blue-600 rounded-full hover:bg-blue-500">Send</button>
            </form>
          </div>
        ) : (
          <button
            onClick={() => setChatOpen(true)}
            className="flex items-center gap-2 px-6 py-3.5 text-base font-medium bg-gradient-to-r from-blue-600 to-indigo-600 rounded-full shadow-xl hover:shadow-blue-500/40 hover:scale-105 transition-all border border-blue-400/30"
          >
            💬 Ask AI Guide
          </button>
        )}
      </div>

      {/* Other controls can be added similarly... */}
    </div>
  );
});
